// 读取配置：关键词列表
const keywords = (process.env.TREND_KEYWORDS || 'MBTI').split(',');
const searchEngines = ['google', 'baidu', 'weibo'];
const items = [];

for (const keyword of keywords) {
  for (const engine of searchEngines) {
    items.push({
      json: {
        keyword: keyword.trim(),
        engine: engine,
        timestamp: new Date().toISOString()
      }
    });
  }
}

return items;

// 提取搜索结果
const input = $input.first().json;
const results = input.organic_results || [];
const items = [];

for (const result of results.slice(0, 5)) {
  // 计算热度值（基于排名）
  const position = result.position || 10;
  const hotScore = Math.max(100 - position * 10, 10);

  items.push({
    json: {
      title: result.title || '无标题',
      url: result.link || '',
      snippet: result.snippet || '',
      source: $('准备搜索任务').item.json.engine,
      keyword: $('准备搜索任务').item.json.keyword,
      hotScore: hotScore,
      position: position,
      timestamp: new Date().toISOString()
    }
  });
}

return items;

// 提取HTML文本内容
const html = $input.first().json.data || '';

// 简单的HTML清理（移除标签）
let text = html
  .replace(/<script[^>]*>.*?<\/script>/gi, '')
  .replace(/<style[^>]*>.*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// 截取前1000字
text = text.substring(0, 1000);

const prevData = $('提取搜索结果').item.json;

return [{
  json: {
    ...prevData,
    content: text,
    contentLength: text.length
  }
}];

