// 整合数据
const prevData = $('提取文本内容').item.json;
const aiResponse = $input.first().json;

// 解析AI返回的JSON
let analysis = {
  summary: prevData.snippet,
  keywords: [prevData.keyword],
  category: ['未分类'],
  audience: ['通用'],
  sentiment: '中性',
  relevance: 5
};

try {
  const aiContent = aiResponse.choices?.[0]?.message?.content || '{}';
  const match = aiContent.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    analysis = { ...analysis, ...parsed };
  }
} catch (e) {
  // 使用默认值
}

return [{
  json: {
    title: prevData.title,
    source: prevData.source,
    sourceUrl: prevData.url,
    summary: analysis.summary,
    content: prevData.content,
    hotScore: prevData.hotScore,
    keywords: analysis.keywords,
    category: analysis.category,
    audience: analysis.audience,
    sentiment: analysis.sentiment,
    relevance: analysis.relevance,
    status: '待筛选',
    discoveredAt: prevData.timestamp
  }
}];

// 构建Notion请求体
const d = $json;
const body = {
  parent: { database_id: process.env.NOTION_HOTSPOT_DB_ID },
  properties: {
    '标题': { title: [{ text: { content: d.title.substring(0, 100) } }] },
    '来源': { select: { name: d.source } },
    '来源URL': { url: d.sourceUrl },
    '摘要': { rich_text: [{ text: { content: d.summary.substring(0, 2000) } }] },
    '热度值': { number: d.hotScore },
    '发现时间': { date: { start: d.discoveredAt } },
    '关键词': { multi_select: d.keywords.slice(0, 5).map(k => ({ name: k })) },
    '分类': { multi_select: d.category.slice(0, 3).map(c => ({ name: c })) },
    '目标受众': { multi_select: d.audience.slice(0, 3).map(a => ({ name: a })) },
    '情感倾向': { select: { name: d.sentiment } },
    '状态': { select: { name: d.status } }
  }
};
return [{ json: { notionBody: JSON.stringify(body), originalData: d } }];

// 生成执行摘要
const items = $input.first().json.data || [];
const successCount = items.filter(item => item.id).length;
const failCount = items.length - successCount;

const summary = `热点抓取报告
==================
执行时间: ${new Date().toLocaleString('zh-CN')}

【抓取结果】
- 成功: ${successCount}条
- 失败: ${failCount}条
- 总计: ${items.length}条

【热点分布】
${items.slice(0, 5).map((item, i) => `${i+1}. ${item.originalData?.title || '未知'} (热度:${item.originalData?.hotScore || 0})`).join('\n')}

【下一步】
1. 在Notion热点库中查看详情
2. 筛选高质量热点
3. 转入素材库进行深度分析`;

return [{
  json: {
    report: summary,
    successCount,
    failCount,
    totalCount: items.length,
    timestamp: new Date().toISOString()
  }
}];
